3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * The single normalization rule for owner addresses: trim, collapse runs of whitespace to a
8	 * single space, upper-case, and expand common street-type abbreviations (ST->STREET, RD->ROAD,
9	 * AVE->AVENUE). Shared by {@link NormalizeOwnerAddress} (which stores the normalized value on the
10	 * request) so every address is stored, returned and compared — duplicate-household detection and
11	 * the shared household id (see {@link OwnerHouseholds}) — in the same form.
12	 */
13	final class OwnerAddresses {
14	
15	    /** Upper-cased abbreviation -> its expansion, matched a whole word at a time. */
16	    private static final Map<String, String> ABBREVIATIONS = Map.of(
17	            "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
18	
19	    private OwnerAddresses() {
20	    }
21	
22	    /**
23	     * The stored form of an address: trimmed, internal whitespace collapsed, upper-cased and with
24	     * common street-type abbreviations expanded. A {@code null} or blank input normalizes to the
25	     * empty string.
26	     */
27	    static String normalize(String address) {
28	        if (address == null || address.isBlank()) {
29	            return "";
30	        }
31	        String[] words = address.trim().toUpperCase(Locale.ROOT).split("\\s+");
32	        StringBuilder normalized = new StringBuilder(address.length());
33	        for (String word : words) {
34	            if (normalized.length() > 0) {
35	                normalized.append(' ');
36	            }
37	            normalized.append(ABBREVIATIONS.getOrDefault(word, word));
38	        }
39	        return normalized.toString();
40	    }
41	}
