3	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
4	
5	/**
6	 * The single normalization rule for owner telephones: convert a raw telephone to E.164
7	 * form. Spaces, dashes and brackets are stripped; a leading {@code +} with its country
8	 * code is kept, otherwise country code {@code +61} is assumed and a single leading
9	 * {@code 0} is dropped from the national digits. The result must carry 8 to 15 digits
10	 * after the {@code +}. Shared by {@link NormalizeOwnerTelephone} (which stores the E.164
11	 * value on the request) so every telephone is stored and compared the same way.
12	 */
13	final class OwnerTelephones {
14	
15	    private static final String DEFAULT_COUNTRY_CODE = "61";
16	    private static final int MIN_DIGITS = 8;
17	    private static final int MAX_DIGITS = 15;
18	
19	    private OwnerTelephones() {
20	    }
21	
22	    /**
23	     * The E.164 form of {@code telephone} (a leading {@code +} followed by 8 to 15 digits).
24	     *
25	     * @throws InvalidTelephoneException when the value cannot form a valid E.164 number.
26	     */
27	    static String toE164(String telephone) throws InvalidTelephoneException {
28	        String cleaned = (telephone == null ? "" : telephone).replaceAll("[\\s()-]", "");
29	
30	        String digits;
31	        if (cleaned.startsWith("+")) {
32	            digits = cleaned.substring(1);
33	        } else {
34	            digits = dropSingleLeadingZero(cleaned);
35	            digits = DEFAULT_COUNTRY_CODE + digits;
36	        }
37	
38	        if (!digits.matches("\\d+") || digits.length() < MIN_DIGITS || digits.length() > MAX_DIGITS) {
39	            throw new InvalidTelephoneException(
40	                    "Telephone must form a valid E.164 number with " + MIN_DIGITS + " to " + MAX_DIGITS
41	                            + " digits after the country code");
42	        }
43	        return "+" + digits;
44	    }
45	
46	    private static String dropSingleLeadingZero(String digits) {
47	        return digits.startsWith("0") ? digits.substring(1) : digits;
48	    }
49	}
