6	/**
7	 * The single rule set for owner email addresses: what counts as "present", what counts as
8	 * a syntactically valid address, and how one is normalized for storage. Shared so every step
9	 * that touches an owner email treats it the same way.
10	 */
11	final class OwnerEmails {
12	
13	    /** local-part {@code @} domain, no whitespace, and a dotted domain. */
14	    private static final Pattern SYNTAX = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
15	
16	    private OwnerEmails() {
17	    }
18	
19	    /** An email is present when it is non-null and not blank; blank is treated as omitted. */
20	    static boolean isPresent(String email) {
21	        return email != null && !email.isBlank();
22	    }
23	
24	    /** Whether {@code email} is a syntactically valid address. */
25	    static boolean isValid(String email) {
26	        return email != null && SYNTAX.matcher(email).matches();
27	    }
28	
29	    /** The stored form of an email: trimmed and lower-cased. */
30	    static String normalize(String email) {
31	        return email.trim().toLowerCase(Locale.ROOT);
32	    }
33	}
