1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.ArrayList;
7	import java.util.List;
8	import java.util.Locale;
9	
10	import org.springframework.samples.petclinic.model.Owner;
11	
12	/**
13	 * The single definition of what a "household" is: owners sharing the same last name and
14	 * address, compared case-insensitively with runs of whitespace collapsed to a single
15	 * space. Shared by {@link RejectDuplicateOwnerHousehold} (which forbids an unopted
16	 * duplicate) and {@link AssignOwnerHousehold} (which links opted-in members), so both
17	 * decide membership identically.
18	 */
19	final class OwnerHouseholds {
20	
21	    private static final int ID_HEX_LENGTH = 12;
22	
23	    private OwnerHouseholds() {
24	    }
25	
26	    /** The existing owners that share the household identified by {@code lastName} and {@code address}. */
27	    static List<Owner> members(Iterable<Owner> owners, String lastName, String address) {
28	        String canonicalLastName = canonical(lastName);
29	        String canonicalAddress = canonical(address);
30	        List<Owner> members = new ArrayList<>();
31	        for (Owner existing : owners) {
32	            if (canonicalLastName.equals(canonical(existing.getLastName()))
33	                    && canonicalAddress.equals(canonical(existing.getAddress()))) {
34	                members.add(existing);
35	            }
36	        }
37	        return members;
38	    }
39	
40	    /**
41	     * A stable identifier for the household: derived from the canonical last name and
42	     * address, so every member computes the same value regardless of creation order.
43	     */
44	    static String householdId(String lastName, String address) {
45	        String key = canonical(lastName) + "�" + canonical(address);
46	        try {
47	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
48	            StringBuilder hex = new StringBuilder(ID_HEX_LENGTH);
49	            for (int i = 0; hex.length() < ID_HEX_LENGTH; i++) {
50	                hex.append(String.format("%02X", digest[i] & 0xFF));
51	            }
52	            return hex.substring(0, ID_HEX_LENGTH);
53	        } catch (NoSuchAlgorithmException ex) {
54	            throw new IllegalStateException("SHA-256 is required to derive a household id", ex);
55	        }
56	    }
57	
58	    /** Trim, collapse internal whitespace to a single space, and lower-case for comparison. */
59	    private static String canonical(String value) {
60	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
61	    }
62	}
